    // retained per step, with bodyCentre / up / groundOffsetUnits kept SEPARATELY
    // as their own measurements. Nothing here derives one from the other.
    bodyPose: cg?.bodyPose ?? null, bodyCentre: cg?.bodyCentre ?? null,
