    holdReason: cg?.holdReason ?? null, survey: cg?.survey ?? null, worker: cg?.worker ?? null,
    pointerLockIsCanvas: ctl?.pointerLockIsCanvas ?? null, hasFocus: ctl?.hasFocus ?? null,
