  };
  report.stalls.push(rec); emit({ phase: 'stall-diagnosis', ...rec });
  say(`STALL at ${where}: hold=${rec.holdReason} supported=${rec.supported} lock=${rec.pointerLockIsCanvas} focus=${rec.hasFocus}`);
  return rec;
};

// ------------------------------------------------------------ ordinary walk ----
