      report.legs.push(leg); emit({ phase: 'leg', ...leg }); say(`LEG ${label} REACHED d=${d.toFixed(2)}`); return leg;
    }
    const want = unit2([target[0] - p[0], target[2] - p[2]]) ?? [1, 0];
    const pick = chooseKey(dirs, want);
    if (!pick.key) break;
